/* ------------------------------ scaling helpers ------------------------------ */

/** Deterministic 0-1 hash from a string + salt (no RNG — stable across renders/SSR). */
const seeded = (key: string, salt: number): number => {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 1000) / 1000;
};

/** Multiplicative jitter in [1-spread, 1+spread] so regions don't look copy-pasted. */
const jitter = (key: string, salt: number, spread = 0.08) => 1 + (seeded(key, salt) * 2 - 1) * spread;

const round = (n: number, dp = 0) => {
  const f = 10 ** dp;
  return Math.round(n * f) / f;
};

/** Scale the global baseline to a region: counts scale by factor, rates/ratios only jitter. */
export function scaleAnalytics(
  code: string,
  name: string,
  factor: number,
  macro?: MacroRegion,
): RegionAnalytics {
  const j = (salt: number, spread?: number) => jitter(code, salt, spread);
  const cnt = (v: number, salt: number) => Math.round(v * factor * j(salt));
  const pct = (v: number, salt: number) => round(Math.min(97, v * j(salt, 0.06)), 1);
  const num = (v: number, salt: number, dp = 1) => round(v * j(salt, 0.07), dp);

  const b = GLOBAL_BASE;
  const gamified = cnt(b.screenTime.gamified, 31);
  const viewers = Math.max(gamified + 1, cnt(b.screenTime.viewers, 30));
  const signups = cnt(b.monetization.funnel.signups, 40);
  const firstSession = Math.round(signups * 0.8 * j(41, 0.04));
  const engaged = Math.round(firstSession * 0.6 * j(42, 0.05));
  const subscribed = cnt(b.monetization.funnel.subscribed, 43);

  return {
    code,
    name,
    macro,
    factor,
    strip: {
      users: cnt(b.strip.users, 1),
      subscribers: cnt(b.strip.subscribers, 2),
      onlineNow: cnt(b.strip.onlineNow, 3),
      playingNow: cnt(b.strip.playingNow, 4),
    },
    userAnalytics: {
      starts: cnt(b.userAnalytics.starts, 10),
      completes: cnt(b.userAnalytics.completes, 11),
      avgWatchPct: pct(b.userAnalytics.avgWatchPct, 12),
      avgWatchSecs: num(b.userAnalytics.avgWatchSecs, 13),
      avgClipSecs: num(b.userAnalytics.avgClipSecs, 14),
      swipeThroughPct: pct(b.userAnalytics.swipeThroughPct, 15),
      rewatchLoops: num(b.userAnalytics.rewatchLoops, 16),
      engagementPerSession: num(b.userAnalytics.engagementPerSession, 17),
      videosPerSession: num(b.userAnalytics.videosPerSession, 18),
      videosPerDay: num(b.userAnalytics.videosPerDay, 19, 0),
      completionLivePct: pct(b.userAnalytics.completionLivePct, 20),
      hitRatePct: pct(b.userAnalytics.hitRatePct, 21),
    },
    gamification: {
      earnedPerUserDay: num(b.gamification.earnedPerUserDay, 50, 0),
      redemptionPct: pct(b.gamification.redemptionPct, 51),
      pointsOutstanding: cnt(b.gamification.pointsOutstanding, 52),
      streakAvgDays: num(b.gamification.streakAvgDays, 53),
      streakLongestDays: num(b.gamification.streakLongestDays, 54, 0),
      leaderboardChecksPerWeek: num(b.gamification.leaderboardChecksPerWeek, 55),
      rankChangeAvgWeek: num(b.gamification.rankChangeAvgWeek, 56, 0),
      challengeParticipationPct: pct(b.gamification.challengeParticipationPct, 57),
      challengeCompletionPct: pct(b.gamification.challengeCompletionPct, 58),
      earnedBySource: b.gamification.earnedBySource,
      balanceBuckets: b.gamification.balanceBuckets,
      economyTrend: b.gamification.economyTrend.map((r, i) => ({
        period: r.period,
        distributed: cnt(r.distributed, 60 + i),
        redeemed: cnt(r.redeemed, 70 + i),
      })),
      redemptionTrend: b.gamification.redemptionTrend.map((r, i) => ({
        week: r.week,
        rate: pct(r.rate, 80 + i),
      })),
    },
    screenTime: {
      viewers,
      gamified,
      sessionAvgSecs: Math.round(b.screenTime.sessionAvgSecs * j(90, 0.1)),
      sessionMedianSecs: Math.round(b.screenTime.sessionMedianSecs * j(91, 0.1)),
      sessionBuckets: b.screenTime.sessionBuckets,
      heatmap: buildHeatmap(0.85 + seeded(code, 92) * 0.3),
      bgFgPerSession: num(b.screenTime.bgFgPerSession, 93),
      doomscrollVideos: num(b.screenTime.doomscrollVideos, 94, 0),
      doomscrollMinutes: num(b.screenTime.doomscrollMinutes, 95, 0),
    },
    monetization: {
      arpu: num(b.monetization.arpu, 100, 2),
      arpdau: num(b.monetization.arpdau, 101, 2),
      trialToPaidPct: pct(b.monetization.trialToPaidPct, 102),
      ltvCacRatio: num(b.monetization.ltvCacRatio, 103),
      funnel: {
        signups,
        firstSession,
        engaged,
        subscribed: Math.min(subscribed, engaged),
        referred: Math.round(signups * 0.25 * j(44, 0.1)),
      },
      channels: b.monetization.channels.map((c, i) => ({
        channel: c.channel,
        ltv: num(c.ltv, 110 + i, 0),
        cac: num(c.cac, 120 + i, 0),
      })),
      subsTrend: b.monetization.subsTrend.map((r, i) => ({
        date: r.date,
        newSubs: cnt(r.newSubs, 130 + i),
        cancellations: cnt(r.cancellations, 150 + i),
      })),
      revenueTrend: b.monetization.revenueTrend.map((r, i) => ({
        month: r.month,
        subscriptions: cnt(r.subscriptions, 170 + i),
      })),
    },
    community: {
      inApp: {
        commentsPerUserWeek: num(b.community.inApp.commentsPerUserWeek, 200),
        replyRatePct: pct(b.community.inApp.replyRatePct, 201),
        reactionToViewPct: num(b.community.inApp.reactionToViewPct, 202),
        sharesPerVideo: num(b.community.inApp.sharesPerVideo, 203, 0),
      },
      external: {
        mentionsPerWeek: cnt(b.community.external.mentionsPerWeek, 210),
        sentiment: b.community.external.sentiment,
        viralMoments: Math.max(1, cnt(b.community.external.viralMoments, 211)),
        organicImpressions: cnt(b.community.external.organicImpressions, 212),
        earnedMediaValue: cnt(b.community.external.earnedMediaValue, 213),
        topAdvocates: Math.max(1, cnt(b.community.external.topAdvocates, 214)),
      },
    },
    graphs: {
      retention: {
        d1: pct(b.graphs.retention.d1, 220),
        d7: pct(b.graphs.retention.d7, 221),
        d30: pct(b.graphs.retention.d30, 222),
        series: b.graphs.retention.series.map((r, i) => ({
          day: r.day,
          current: r.day === "D0" ? 100 : pct(r.current, 230 + i),
          previous: r.day === "D0" ? 100 : pct(r.previous, 240 + i),
        })),
      },
      kFactor: b.graphs.kFactor.map((r, i) => ({ month: r.month, k: num(r.k, 250 + i, 2) })),
      velocity: b.graphs.velocity.map((r, i) => ({ day: r.day, players: cnt(r.players, 260 + i) })),
    },
  };
}

/* ------------------------------ REGION_ANALYTICS ------------------------------ */

// Slide-6 share of the engaged base per macro-region (map shows only top countries,
// so a macro's factor exceeds the sum of its visible countries).
const MACRO_FACTORS: Record<MacroRegion, number> = {
  NA: 0.29,
  EU: 0.24,
  APAC: 0.56,
  LATAM: 0.1,
  MEA: 0.05,
};

// The master viewership table (slide 6): keep these exact values on macro pages so the
// master table and each region's own split agree.
const MACRO_VIEWERSHIP: Record<MacroRegion, { viewers: number; gamified: number }> = {
  NA: { viewers: 18400, gamified: 11200 },
  EU: { viewers: 12100, gamified: 6900 },
  APAC: { viewers: 22900, gamified: 15800 },
  LATAM: { viewers: 6300, gamified: 3400 },
  MEA: { viewers: 3100, gamified: 1500 },
};

const buildRegionAnalytics = (): Record<string, RegionAnalytics> => {
  const out: Record<string, RegionAnalytics> = {};

  // Global = the untouched baseline.
  out["global"] = { code: "global", name: "Global", factor: 1, ...GLOBAL_BASE };

  for (const r of MACRO_REGIONS) {
    const entry = scaleAnalytics(r.code, r.label, MACRO_FACTORS[r.code]);
    // pin the viewers/gamified split to the master table's exact numbers
    entry.screenTime.viewers = MACRO_VIEWERSHIP[r.code].viewers;
    entry.screenTime.gamified = MACRO_VIEWERSHIP[r.code].gamified;
    out[r.code] = entry;
  }

  const totalUsers = COUNTRY_DATA.reduce((s, c) => s + c.users, 0);
  for (const c of COUNTRY_DATA) {
    const entry = scaleAnalytics(c.code, c.name, c.users / totalUsers, regionForCountry(c.code));
    // the map and the country strip must agree on users
    entry.strip.users = c.users;
    out[c.code] = entry;
  }

  return out;
};

export const REGION_ANALYTICS: Record<string, RegionAnalytics> = buildRegionAnalytics();

/** Lookup that tolerates lower/upper case; returns undefined for unknown codes. */
export function getRegionAnalytics(code: string): RegionAnalytics | undefined {
  return REGION_ANALYTICS[code] ?? REGION_ANALYTICS[code.toUpperCase()] ?? (code.toLowerCase() === "global" ? REGION_ANALYTICS["global"] : undefined);
}

/* ------------------------------ format helpers ------------------------------ */

export const fmtCount = (v: number): string =>
  v >= 1_000_000 ? `${(v / 1_000_000).toFixed(2)}M` : v >= 10_000 ? `${(v / 1000).toFixed(1)}K` : v.toLocaleString();

export const fmtMoney = (v: number): string =>
  v >= 1_000_000 ? `$${(v / 1_000_000).toFixed(1)}M` : v >= 1000 ? `$${(v / 1000).toFixed(0)}K` : `$${v.toFixed(2)}`;

export const fmtDuration = (secs: number): string => {
  const m = Math.floor(secs / 60);
  const s = Math.round(secs % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
};

